ON MAIN.ConfigValue = ShP.ConfigValue AND main.[BusinessPartner]=ShP.[BusinessPartner] 
Where  MAIN.ConfigValue is not null and len(MAIN.ConfigValue)>0', '1', 'INSERT INTO #DMS_FactL2Monitor
